import { type ReactNode } from 'react';

type AvatarType = 'image' | 'image-border' | 'initials' | 'icon';
type AvatarShape = 'circle' | 'square';
type AvatarSize = 'xs' | 's' | 'm' | 'l';

export type AvatarProps = {
  type?: AvatarType;
  shape?: AvatarShape;
  size?: AvatarSize;
  src?: string;
  alt?: string;
  initials?: string;
  icon?: ReactNode;
  status?: boolean;
  skeleton?: boolean;
  className?: string;
};

function cn(...classes: (string | false | undefined | null)[]) {
  return classes.filter(Boolean).join(' ');
}

const DefaultIcon = () => (
  <svg width="100%" height="100%" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" strokeDasharray="2 2">
    <circle cx="8" cy="6" r="3" />
    <path d="M3 14a5 5 0 0110 0" />
  </svg>
);

export function Avatar({
  type = 'image-border',
  shape = 'circle',
  size = 's',
  src,
  alt = '',
  initials,
  icon,
  status = false,
  skeleton = false,
  className,
}: AvatarProps) {
  const classes = cn(
    'avatar',
    `avatar--${type}`,
    `avatar--${shape}`,
    `avatar--${size}`,
    skeleton && 'avatar--skeleton',
    className,
  );

  const renderContent = () => {
    if (skeleton) return null;

    if (type === 'image' || type === 'image-border') {
      return src ? <img className="avatar__image" src={src} alt={alt} /> : <span className="avatar__icon"><DefaultIcon /></span>;
    }

    if (type === 'initials') {
      return <span>{initials || '??'}</span>;
    }

    if (type === 'icon') {
      return <span className="avatar__icon">{icon || <DefaultIcon />}</span>;
    }

    return null;
  };

  return (
    <span className={classes}>
      {renderContent()}
      {status && !skeleton && <span className="avatar__status" />}
    </span>
  );
}

/* -------------------------------------------------------------------------
   Avatar

   User representation: image, initials, or icon placeholder.
   Optional status dot (online indicator).

   Types:   image, image-border, initials, icon
   Shapes:  circle, square
   Sizes:   xs (24px), s (32px), m (40px), l (48px)
   ------------------------------------------------------------------------- */

.avatar {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  position: relative;
  background-color: var(--muted);
}

.avatar__image {
  overflow: hidden;
}

/* ---- Sizes ---- */

.avatar--xs { width: 1.5rem; height: 1.5rem; }
.avatar--s  { width: 2rem; height: 2rem; }
.avatar--m  { width: 2.5rem; height: 2.5rem; }
.avatar--l  { width: 3rem; height: 3rem; }

/* ---- Shapes ---- */

.avatar--circle { border-radius: var(--radius-full); }

.avatar--square.avatar--xs { border-radius: var(--radius-md); }
.avatar--square.avatar--s  { border-radius: var(--radius-md); }
.avatar--square.avatar--m  { border-radius: var(--radius-lg); }
.avatar--square.avatar--l  { border-radius: var(--radius-xl); }

/* ---- Types ---- */

/* Image (no border) */
.avatar--image {
  background: none;
  padding: 0;
}

/* Image with border ring */
.avatar--image-border {
  padding: 0.125rem;
}
.avatar--image-border.avatar--m,
.avatar--image-border.avatar--l {
  padding: 0.25rem;
}

/* Initials */
.avatar--initials {
  border: var(--stroke-medium) solid var(--border);
  font-family: var(--font-family-sans), ui-sans-serif, system-ui, sans-serif;
  font-weight: var(--font-weight-regular);
  color: var(--border-focus);
  font-size: var(--font-size-sm);
  line-height: 1;
}
.avatar--initials.avatar--l {
  font-size: var(--font-size-base);
}

/* Icon */
.avatar--icon {
  border: var(--stroke-medium) solid var(--border);
  color: var(--muted-foreground);
}

/* ---- Image element ---- */

.avatar__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  border-radius: inherit;
}

.avatar--circle .avatar__image {
  border-radius: var(--radius-full);
}

/* ---- Icon element ---- */

.avatar__icon {
  display: flex;
  align-items: center;
  justify-content: center;
}

.avatar--xs .avatar__icon { width: 0.75rem; height: 0.75rem; }
.avatar--s .avatar__icon  { width: 1rem; height: 1rem; }
.avatar--m .avatar__icon  { width: 1.25rem; height: 1.25rem; }
.avatar--l .avatar__icon  { width: 1.5rem; height: 1.5rem; }

.avatar__icon svg {
  width: 100%;
  height: 100%;
}

/* ---- Status dot ---- */

.avatar__status {
  position: absolute;
  background-color: var(--success);
  border-radius: var(--radius-full);
  border-style: solid;
  border-color: var(--background);
}

.avatar--xs .avatar__status { width: 0.5rem; height: 0.5rem; border-width: var(--stroke-hairline); bottom: -0.0625rem; right: -0.0625rem; }
.avatar--s .avatar__status  { width: 0.5rem; height: 0.5rem; border-width: var(--stroke-hairline); bottom: 0; right: 0; }
.avatar--m .avatar__status  { width: 0.75rem; height: 0.75rem; border-width: var(--stroke-thin); bottom: 0; right: 0; }
.avatar--l .avatar__status  { width: 1rem; height: 1rem; border-width: var(--stroke-medium); bottom: 0; right: 0; }

/* ---- Skeleton ---- */

.avatar--skeleton {
  border: none;
  animation: avatar-skeleton-pulse 1.5s ease-in-out infinite;
}

.avatar--skeleton * {
  display: none;
}

@keyframes avatar-skeleton-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.5; }
}

